window.GMT_FIREBASE_AUTH = firebase.auth();
window.GMT_CURRENT_USER = window.GMT_FIREBASE_AUTH.currentUser || null;

window.GMT_FIREBASE_AUTH.onAuthStateChanged(function (user) {
  window.GMT_CURRENT_USER = user || null;
});

window.getGMTFirebaseToken = async function () {
  var auth = window.GMT_FIREBASE_AUTH;

  if (!auth) {
    throw new Error(
      "GaveAI Firebase Authentication is not initialized."
    );
  }

  var user = auth.currentUser;

  if (!user) {
    user = await new Promise(function (resolve) {
      var resolved = false;

      var unsubscribe = auth.onAuthStateChanged(
        function (currentUser) {
          if (!resolved) {
            resolved = true;

            try {
              unsubscribe();
            } catch (e) {}

            resolve(currentUser || null);
          }
        }
      );

      setTimeout(function () {
        if (!resolved) {
          resolved = true;

          try {
            unsubscribe();
          } catch (e) {}

          resolve(auth.currentUser || null);
        }
      }, 3000);
    });
  }

  if (!user) {
    throw new Error(
      "User authentication is required. Please sign in to your account before using GaveAI tools."
    );
  }

  window.GMT_CURRENT_USER = user;

  var token = await user.getIdToken(false);

  if (!token) {
    token = await user.getIdToken(true);
  }

  if (!token) {
    throw new Error(
      "Unable to obtain Firebase authentication token."
    );
  }

  return token;
};

async function getGaveAIAuthHeaders(isFormData = false) {
  const token = await window.getGMTFirebaseToken();

  const headers = {
    "Authorization": "Bearer " + token,
    "Accept": "application/json"
  };

  if (!isFormData) {
    headers["Content-Type"] = "application/json";
  }

  return headers;
}
