.sb-close-btn{background:rgba(255,255,255,0.2);border:none;color:#fff;width:36px;height:36px;border-radius:50%;cursor:pointer;font-size:18px;font-weight:700;display:flex;align-items:center;justify-content:center;transition:all 0.2s}
.sb-close-btn:hover{background:rgba(255,255,255,0.3);transform:scale(1.05)}

.sb-main{flex:1;display:grid;grid-template-columns:340px 1fr;gap:0;overflow:hidden}
