.sb-sidebar-title{font-family:"Poppins",sans-serif;font-size:13px;font-weight:800;color:#1e3a8a;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:10px;display:flex;align-items:center;gap:6px}
.sb-input-group{margin-bottom:12px}
.sb-input-group label{display:block;font-size:11px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:0.3px;margin-bottom:4px}
.sb-input-group textarea,.sb-input-group input{width:100%;padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;font-family:inherit;outline:none;transition:border-color 0.2s,box-shadow 0.2s;background:#fff;resize:vertical}
.sb-input-group textarea:focus,.sb-input-group input:focus{border-color:#0284c7;box-shadow:0 0 0 3px rgba(2,132,199,0.15)}
