.sb-scene-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:10px}
.sb-scene-number{font-family:"Poppins",sans-serif;font-size:14px;font-weight:800;color:#1e3a8a;display:flex;align-items:center;gap:8px}
.sb-scene-number span{background:#1e3a8a;color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px}
.sb-scene-actions{display:flex;gap:4px}
.sb-scene-btn{background:#f1f5f9;border:1px solid #e2e8f0;color:#475569;width:30px;height:30px;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:13px;transition:all 0.2s}
.sb-scene-btn:hover{background:#e2e8f0;color:#1e3a8a}
