.sb-scene-body{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:12px}
.sb-scene-media{display:flex;flex-direction:column;gap:8px}
.sb-image-preview{width:100%;aspect-ratio:16/9;background:#f1f5f9;border:2px dashed #cbd5e1;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:12px;font-weight:600;overflow:hidden;position:relative}
.sb-image-preview.has-image{border-style:solid;border-color:#e2e8f0}
.sb-image-preview img{width:100%;height:100%;object-fit:cover}
.sb-media-buttons{display:flex;gap:6px;flex-wrap:wrap}
.sb-media-btn{background:#fff;border:1px solid #cbd5e1;color:#475569;padding:6px 10px;border-radius:6px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:4px;transition:all 0.2s}
