  .sb-footer{flex-direction:column;align-items:stretch}
  .sb-footer-left{justify-content:center;flex-wrap:wrap}
  .sb-generate-final-btn{width:100%;justify-content:center}
}
@media(max-width:600px){.ai-box{right:10px;bottom:84px;width:calc(100vw - 20px);height:70vh}.ai-assistant-widget{right:10px;bottom:15px}.mic-modal{padding:24px}}
.post-layout{display:grid;grid-template-columns:1fr 300px;gap:32px;align-items:start;max-width:1280px;margin:0 auto;padding:36px 20px 60px}
.post-main{min-width:0}
.sidebar{display:flex;flex-direction:column;gap:20px}
.sidebar-widget{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:20px}
.widget-title{font-family:'Poppins',sans-serif;font-size:1.1rem;color:#1e3a8a;font-weight:800;padding-bottom:10px;border-bottom:2px solid #f97316;margin-bottom:16px}
.contact-form-group{margin-bottom:14px}
.contact-form-label{display:block;font-size:11px;font-weight:800;color:#1e3a8a;margin-bottom:6px;text-transform:uppercase}
.contact-form-input,.contact-form-textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:12px;font-size:14px;outline:none}
.contact-form-textarea{min-height:100px;resize:vertical}
.contact-form-btn{width:100%;background:#f97316;color:#fff;border:none;border-radius:8px;padding:14px;font-weight:800;font-size:14px;text-transform:uppercase;cursor:pointer}
@media(max-width:1024px){.footer-grid{grid-template-columns:1fr 1fr}.post-layout{grid-template-columns:1fr}}
@media(max-width:640px){.footer-grid{grid-template-columns:1fr}.ai-box{width:100%;height:100%;bottom:0;right:0;border-radius:0}}

body.script:
//

const GAVEAI_BACKEND_URL = "https://gaveai-backend.onrender.com";
let uploadedFileBase64 = null;
let uploadedFileType = null;
let currentUpload = null;
let uploadedMediaUrl = null;

/* ==========================================
   WHATSAPP-STYLE MICROPHONE MODAL
   ========================================== */
let micModalOpen = false;
let micRecording = false;
let micMediaRecorder = null;
let micAudioChunks = [];
let micStream = null;

window.openMicModal = function() {
  const overlay = document.getElementById('micModalOverlay');
  if (!overlay) return;
  overlay.classList.add('open');
  micModalOpen = true;
  resetMicUI();
};

window.closeMicModal = function() {
  const overlay = document.getElementById('micModalOverlay');
  if (!overlay) return;
  overlay.classList.remove('open');
  micModalOpen = false;
  if (micRecording) {
    stopMicRecording();
  }
  if (micStream) {
    micStream.getTracks().forEach(t => t.stop());
    micStream = null;
  }
};

function resetMicUI() {
  const title = document.getElementById('micModalTitle');
  const subtitle = document.getElementById('micModalSubtitle');
  const status = document.getElementById('micStatus');
  const recordBtn = document.getElementById('micRecordBtn');
  if (title) title.innerText = 'Turn off microphone';
  if (subtitle) subtitle.innerText = navigator.mediaDevices ? 'Device Microphone (Built-in)' : 'Microphone';
  if (status) { status.innerText = 'Tap to start recording'; status.classList.remove('recording'); }
  if (recordBtn) recordBtn.classList.remove('recording');
}

window.handleMicRecord = async function() {
  if (micRecording) {
    stopMicRecording();
  } else {
    await startMicRecording();
  }
};

window.handleMicCancel = function() {
  if (micRecording) {
    stopMicRecording();
    micAudioChunks = [];
  }
  closeMicModal();
};

async function startMicRecording() {
  try {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      alert('Your browser does not support microphone recording. Please use Chrome.');
      return;
    }
    micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    micMediaRecorder = new MediaRecorder(micStream, { mimeType: 'audio/webm' });
    micAudioChunks = [];

    micMediaRecorder.ondataavailable = function(e) {
      if (e.data && e.data.size > 0) micAudioChunks.push(e.data);
    };

    micMediaRecorder.onstop = async function() {
      const audioBlob = new Blob(micAudioChunks, { type: 'audio/webm' });
      await processVoiceMessage(audioBlob);
      micAudioChunks = [];
    };

    micMediaRecorder.start();
    micRecording = true;

    const title = document.getElementById('micModalTitle');
    const status = document.getElementById('micStatus');
    const recordBtn = document.getElementById('micRecordBtn');
    if (title) title.innerText = 'Recording... Tap to stop';
    if (status) { status.innerText = ' Listening...'; status.classList.add('recording'); }
    if (recordBtn) recordBtn.classList.add('recording');

  } catch (err) {
    console.error('Microphone error:', err);
    alert('Microphone access denied or not available.');
  }
}

function stopMicRecording() {
  if (micMediaRecorder && micMediaRecorder.state !== 'inactive') {
    micMediaRecorder.stop();
  }
  micRecording = false;
  const title = document.getElementById('micModalTitle');
  const status = document.getElementById('micStatus');
  const recordBtn = document.getElementById('micRecordBtn');
  if (title) title.innerText = 'Processing voice...';
  if (status) { status.innerText = 'ÃƒÆ’Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒâ€šÃ‚Â³ Sending voice...'; status.classList.remove('recording'); }
  if (recordBtn) recordBtn.classList.remove('recording');
}

async function processVoiceMessage(audioBlob) {
  const status = document.getElementById('micStatus');
  if (status) status.innerText = ' GaveAI is thinking...';

  try {
    const headers = await getGaveAIAuthHeaders(true);
    const formData = new FormData();
    formData.append('audio', audioBlob, 'voice.webm');
    formData.append('imageUrl', uploadedMediaUrl || '');
    formData.append('fileType', uploadedFileType || '');

    const response = await fetch(GAVEAI_BACKEND_URL + '/api/voice/message', {
      method: 'POST',
      headers: headers,
      body: formData
    });

    if (!response.ok) {
      const errText = await response.text();
      throw new Error(errText || 'Voice processing failed');
    }

    const data = await response.json();
    const reply = data.reply || data.response || data.message || data.answer;
    const audioUrl = data.audioUrl || (data.generatedMedia && data.generatedMedia.audioUrl);

    if (reply) {
      addChatMessage(reply, 'bot');
    }

   if (audioUrl) {
  console.log("ÃƒÆ’Ã‚Â°Ãƒâ€¦Ã‚Â¸ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒâ€¦Ã‚Â  GAVEAI AUDIO URL:", audioUrl);
  playAiVoice(audioUrl);
} else if (reply) {
  window.speakText(reply);
}

    if (data.freeVideoRemaining !== undefined) {
      updateFreeVideoDisplay(data.freeVideoRemaining);
    }

    closeMicModal();

  } catch (error) {
    console.error('Voice processing error:', error);
    if (status) status.innerText = ' ' + error.message;
    setTimeout(() => { closeMicModal(); }, 2000);
  }
}

function playAiVoice(audioUrl) {
  const status = document.getElementById('micStatus');
  if (status) status.innerText = 'ÃƒÆ’Ã‚Â°Ãƒâ€¦Ã‚Â¸ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒâ€¦Ã‚Â  GaveAI is speaking...';
  const audio = new Audio(audioUrl);
  audio.play().catch(e => console.warn('Audio playback failed:', e));
  audio.onended = function() {
    closeMicModal();
  };
}

/* ==========================================
   TEXT-TO-SPEECH (AI VOICE OUTPUT - FALLBACK)
   ========================================== */
window.speakText = async function(text) {
  if (!text || !String(text).trim()) return;

  try {
    const cleanText = String(text).trim();

    // Detect language from the text so Tande uses the matching GaveAI voice.
    const lowerText = cleanText.toLowerCase();

    let language = "en";

    if (
      /\b(ki sa|kisa|kijan|poukisa|kilÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¨s|kiyes|ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¨ske|eske|mwen|ou|nan|se|yon|pou|ak|avÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¨k|avek|kreye|pale|kreyÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â²l|kreyol)\b/i.test(lowerText)
    ) {
      language = "ht";
    } else if (
      /\b(quelle|qu'est|qui|quoi|comment|pourquoi|bonjour|je|vous|dans|une|un|avec|parle|franÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â§ais|francais)\b/i.test(lowerText)
    ) {
      language = "fr";
    } else if (
      /\b(hola|buenos|gracias|yo|tÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Âº|tu|para|hablas|espaÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â±ol|espanol)\b/i.test(lowerText)
    ) {
      language = "es";
    }

    const headers = await getGaveAIAuthHeaders(true);

    const response = await fetch(
      GAVEAI_BACKEND_URL + "/api/voice/tts",
      {
        method: "POST",
        headers: {
          ...headers,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          text: cleanText,
          language: language
        })
      }
    );

    const rawText = await response.text();

    let data = null;

    try {
      data = JSON.parse(rawText);
    } catch (e) {
      throw new Error(
        "GaveAI TTS returned an invalid response."
      );
    }

    if (!response.ok) {
      throw new Error(
        data?.error ||
        data?.message ||
        "GaveAI voice generation failed."
      );
    }

    const audioUrl =
      data?.audioUrl ||
      data?.audio ||
      data?.generatedMedia?.audioUrl;

    if (!audioUrl) {
      throw new Error(
        "GaveAI did not return voice audio."
      );
    }

    playAiVoice(audioUrl);

  } catch (error) {
    console.error(
      "GaveAI Tande voice error:",
      error
    );

    // No browser speechSynthesis fallback here.
    // This keeps Haitian Creole on the GaveAI Gemini voice.
  }
};

/* ==========================================
   FETCH WITH AUTH
   ========================================== */
async function fetchJsonSafe(url, options) {
  options = options || {};
  options.headers = { ...(options.headers || {}), ...(await getGaveAIAuthHeaders(false)) };
  const response = await fetch(url, options);
  const rawText = await response.text();
  let data;
  try { data = JSON.parse(rawText); } catch (e) { throw new Error('Backend returned non-JSON response (Status: ' + response.status + ').'); }
  if (!response.ok) { throw new Error(data?.error || data?.message || 'Backend error ' + response.status); }
  return data;
}

/* ==========================================
   FORCE DOWNLOAD (BYPASS CORS)
   ========================================== */
window.forceDownload = async function(url, filename) {
  try {
    const response = await fetch(url);
    const blob = await response.blob();
    const blobUrl = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = filename || 'gaveai-image.jpg';
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.URL.revokeObjectURL(blobUrl);
  } catch (e) {
    console.warn('Direct download failed due to CORS, opening in new tab.', e);
    window.open(url, '_blank');
  }
};

/* ==========================================
   DISPLAY GENERATED MEDIA
   ========================================== */
function displayGeneratedImage(url) {
  const messages = document.getElementById("aiMessages");
  if (!messages || !url) return;

  /*
   * Keep the latest generated image available for the
   * Edit Image workspace flow.
   */
  uploadedMediaUrl = url;
  uploadedFileType = "image";
  currentUpload = {
    file: null,
    type: "image",
    previewUrl: url
  };

  const wrapper = document.createElement("div");
  wrapper.className = "ai-msg bot";

  wrapper.innerHTML =
    '<div>Here is your generated/edited image:</div>' +
    '<div class="ai-media-preview">' +
      '<img src="' + url + '" alt="Generated image" style="max-width:100%; border-radius:10px; margin-top:8px;">' +
    '</div>' +
    '<div class="ai-generated-actions" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;">' +
      '<a href="#" onclick="event.preventDefault(); window.forceDownload(\'' + url + '\', \'gaveai-image.jpg\')" class="ai-action-chip">Download Image</a>' +
      '<button type="button" class="ai-action-chip" onclick="window.openStoryboard();">Edit Image</button>' +
    '</div>';

  messages.appendChild(wrapper);
  messages.scrollTop = messages.scrollHeight;
}

function displayGeneratedVideo(url) {
  const messages = document.getElementById("aiMessages");
  if (!messages || !url) return;

  const wrapper = document.createElement("div");
  wrapper.className = "ai-msg bot";

  wrapper.innerHTML =
    '<div>Here is your generated video:</div>' +
    '<div class="ai-media-preview">' +
      '<video src="' + url + '" controls playsinline style="width:100%; max-width:100%; border-radius:10px; margin-top:8px;"></video>' +
    '</div>' +
    '<div class="ai-generated-actions">' +
      '<a href="' + url + '" target="_blank" rel="noopener" class="ai-action-chip">Open Video</a>' +
      '<a href="#" onclick="event.preventDefault(); window.forceDownload(\'' + url + '\', \'gaveai-video.mp4\')" class="ai-action-chip">Download Video</a>' +
    '</div>';

  messages.appendChild(wrapper);
  messages.scrollTop = messages.scrollHeight;
}

/* ==========================================
   UPLOAD & PREVIEW
   ========================================== */
window.triggerUpload = function(type) {
  const input = document.getElementById(type === "image" ? "imageUploadInput" : "videoUploadInput");
  if (input) input.click();
};

window.handleFileSelect = function(input, type) {
  if (!input || !input.files || !input.files[0]) return;
  const file = input.files[0];
  if (type === "image" && !file.type.startsWith("image/")) { alert("Please select a valid image file."); return; }
  if (type === "video" && !file.type.startsWith("video/")) { alert("Please select a valid video file."); return; }
  const reader = new FileReader();
  reader.onload = function(event) {
    currentUpload = { file: file, type: type, previewUrl: event.target.result };
    uploadedFileBase64 = event.target.result;
    uploadedFileType = type;
    uploadedMediaUrl = null;
    showUploadPreview();
  };
  reader.readAsDataURL(file);
};

function showUploadPreview() {
  const container = document.getElementById("uploadPreviewContainer");
  const content = document.getElementById("uploadPreviewContent");
  const status = document.getElementById("uploadStatus");
  if (!container || !content || !status || !currentUpload) return;
  container.classList.add("has-file");
  if (currentUpload.type === "image") {
    content.innerHTML = '<img src="' + currentUpload.previewUrl + '" class="preview-thumb" alt="Uploaded image">';
    status.innerText = "Image ready: " + (currentUpload.file.name || "Pasted Image");
  } else {
    content.innerHTML = '<video src="' + currentUpload.previewUrl + '" class="preview-thumb" controls></video>';
    status.innerText = "Video ready: " + currentUpload.file.name;
  }
}

window.clearUpload = function() {
  currentUpload = null; uploadedFileBase64 = null; uploadedFileType = null; uploadedMediaUrl = null;
  const container = document.getElementById("uploadPreviewContainer");
  if (container) container.classList.remove("has-file");
  const imgInput = document.getElementById("imageUploadInput");
  const vidInput = document.getElementById("videoUploadInput");
  if (imgInput) imgInput.value = "";
  if (vidInput) vidInput.value = "";
};

async function uploadToImageKit(fileOrBase64, fileType) {
  try {
    const headers = await getGaveAIAuthHeaders(true);
    const formData = new FormData();
    if (typeof fileOrBase64 === 'string' && fileOrBase64.startsWith('data:')) {
      const response = await fetch(fileOrBase64);
      const blob = await response.blob();
      formData.append('file', blob, 'upload.' + fileType);
    } else {
      formData.append('file', fileOrBase64, 'upload.' + fileType);
    }
    const uploadResponse = await fetch(GAVEAI_BACKEND_URL + '/upload-media', {
      method: 'POST', headers: headers, body: formData
    });
    if (!uploadResponse.ok) {
      const errText = await uploadResponse.text();
      throw new Error('Upload failed: ' + errText);
    }
    const result = await uploadResponse.json();
    return result.url || result.fileUrl;
  } catch (error) {
    console.error('ImageKit upload error:', error);
    throw error;
  }
}

/* ==========================================
   AI MESSAGE SENDING (FIXED RESPONSE EXTRACTION)
   ========================================== */
window.sendAiMessage = async function(isVoice) {
  const inputEl = document.getElementById("aiInput");
  const messagesEl = document.getElementById("aiMessages");
  const sendButton = document.getElementById("aiSendBtn");
  if (!inputEl || !messagesEl) return;
  const text = inputEl.value.trim();
  const fileBase64 = uploadedFileBase64;
  const fileType = uploadedFileType;
  if (!text && !fileBase64) return;

  let mediaUrl = null;
  let uploadStatus = null;
  if (fileBase64 && currentUpload) {
    uploadStatus = addChatMessage("ÃƒÆ’Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒâ€šÃ‚Â³ Uploading media to server...", "bot");
    try {
      mediaUrl = await uploadToImageKit(fileBase64, fileType);
      if (uploadStatus) uploadStatus.remove();
      uploadedMediaUrl = mediaUrl;
    } catch (error) {
      if (uploadStatus) uploadStatus.innerText = "ÃƒÆ’Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒâ€¦Ã¢â‚¬â„¢ Upload failed: " + error.message;
      if (sendButton) sendButton.disabled = false;
      return;
    }
  }

  addChatMessage(text || "[Media uploaded]", "user", mediaUrl, fileType);
  inputEl.value = "";
  if (sendButton) sendButton.disabled = true;

  const botMsgDiv = addChatMessage(" Thinking...", "bot");
  try {
    const requestBody = { 
      message: text, 
      file: fileBase64, 
      fileType: fileType, 
      imageUrl: uploadedMediaUrl 
    };
    const data = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/chat", {
      method: "POST", body: JSON.stringify(requestBody)
    });

    const reply = data.reply || data.response || data.message || data.answer;
    if (botMsgDiv) {
      botMsgDiv.innerText = (reply && String(reply).trim()) ? reply : "I couldn't generate a response. Please try again.";
    }

    if (data.generatedMedia && data.generatedMedia.url) {
      if (data.generatedMedia.type === "video") { displayGeneratedVideo(data.generatedMedia.url); }
      else { displayGeneratedImage(data.generatedMedia.url); }
    }

    if (data.freeVideoRemaining !== undefined) { 
      updateFreeVideoDisplay(data.freeVideoRemaining); 
    }

    if (isVoice && reply) {
      setTimeout(function() { window.speakText(reply); }, 500);
    }

  } catch (error) {
    console.error("Chat request error:", error);
    if (botMsgDiv) botMsgDiv.innerText = "ÃƒÆ’Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒâ€¦Ã¢â‚¬â„¢ " + error.message;
  } finally {
    window.clearUpload();
    if (sendButton) sendButton.disabled = false;
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }
};

