};

window.editImageFromInput = async function() {
  const inputEl = document.getElementById("aiInput");

  const activeSceneId =
    window.storyboardGetActiveSceneId
      ? window.storyboardGetActiveSceneId()
      : null;

  const activeScene =
    activeSceneId !== null && Array.isArray(storyboardScenes)
      ? storyboardScenes.find(function(scene) {
          return Number(scene.id) === Number(activeSceneId);
        })
      : null;

  const scenePrompt =
    activeScene && activeScene.prompt
      ? String(activeScene.prompt).trim()
      : "";

  const inputPrompt =
    inputEl && inputEl.value
      ? inputEl.value.trim()
      : "";

  const cleanPrompt = inputPrompt || scenePrompt;

  if (!cleanPrompt) {
    addChatMessage(
      "Please describe what you want to change in the active scene image.",
      "bot"
    );
    return;
  }

  let selectedImageUrl = "";

  if (activeScene) {
    selectedImageUrl =
      String(
        activeScene.imageUrl ||
        activeScene.firstFrameImage ||
        ""
      ).trim();
  }

  if (!selectedImageUrl) {
    selectedImageUrl = String(uploadedMediaUrl || "").trim();
  }

  if (!selectedImageUrl && currentUpload && currentUpload.type === "image") {
    selectedImageUrl =
      String(currentUpload.previewUrl || "").trim();
  }

  if (!selectedImageUrl) {
    addChatMessage(
      "The active scene does not contain an image yet. Generate or upload an image first.",
      "bot"
    );
    return;
  }

  const editBtn = document.getElementById("editImageBtn");
  if (editBtn) editBtn.disabled = true;

  const statusMsg = addChatMessage(
    "ÃƒÆ’Ã‚Â¢Ãƒâ€¦Ã¢â‚¬Å“Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¯Ãƒâ€šÃ‚Â¸Ãƒâ€šÃ‚Â Preparing image for editing... Please wait.",
    "bot"
  );

  try {
    let imageUrl = selectedImageUrl;

    /*
     * If the user selected an image but it has not been uploaded
     * to ImageKit yet, upload it automatically now.
     */
    if (!imageUrl && currentUpload && currentUpload.type === "image") {
      imageUrl = await uploadToImageKit(
        uploadedFileBase64,
        uploadedFileType
      );

      uploadedMediaUrl = imageUrl;
