Make the smallest possible change necessary to satisfy the user's request.
`;

const data = await fetchJsonSafe(
  GAVEAI_BACKEND_URL + "/generate-image",
  {
    method: "POST",
    body: JSON.stringify({
      prompt: strictEditPrompt,
      imageUrl: imageUrl
    })
