window.generateVideoFromInput = async function() {
  const inputEl = document.getElementById("aiInput");
  const cleanPrompt = inputEl ? inputEl.value.trim() : "";

  if (!cleanPrompt) {
    addChatMessage(
      "Please enter a description of the video you want to generate.",
      "bot"
    );
    return;
  }

  const genBtn = document.getElementById("genVideoBtn");

  if (genBtn) {
    genBtn.disabled = true;
  }

  const statusMsg = addChatMessage(
    "Generating video, please wait...",
    "bot"
  );

  try {
    const requestBody = {
      prompt: cleanPrompt,
      width: 832,
      height: 480,
      duration: 5,
      seed: -1
    };

    if (
      currentUpload &&
      currentUpload.type === "image"
    ) {
      requestBody.firstFrameImage =
        uploadedMediaUrl ||
        currentUpload.previewUrl;
    }

    const data = await fetchJsonSafe(
      GAVEAI_BACKEND_URL + "/generate-video",
      {
        method: "POST",
        body: JSON.stringify(requestBody)
      }
    );

    if (
      data.freeVideoRemaining !== undefined
    ) {
      updateFreeVideoDisplay(
        data.freeVideoRemaining
      );
    }

    const immediateMedia =
      data.generatedMedia || {};

    const immediateVideoUrl =
      immediateMedia.video ||
      immediateMedia.url ||
      data.finalVideoUrl ||
      data.videoUrl ||
      data.url ||
      "";

    if (immediateVideoUrl) {
      if (statusMsg) {
        statusMsg.remove();
      }

      displayGeneratedVideo(
        immediateVideoUrl
      );

      if (inputEl) {
        inputEl.value = "";
      }

      return;
    }

    const jobId =
      data.jobId ||
      data.videoJobId ||
      data.productionId ||
      "";

    if (!jobId) {
      throw new Error(
        "GaveAI did not return a video job ID."
      );
    }

    const pollingStartedAt = Date.now();
    const pollingTimeout = 15 * 60 * 1000;

    while (true) {
      if (
        Date.now() - pollingStartedAt >
        pollingTimeout
      ) {
        throw new Error(
          "GaveAI video generation timed out. Please try again."
        );
      }

      if (statusMsg) {
        statusMsg.innerText =
          "Generating video, please wait...";
      }

      await new Promise(function(resolve) {
        setTimeout(resolve, 3000);
      });

      const production =
        await fetchJsonSafe(
          GAVEAI_BACKEND_URL +
            "/api/video-productions/" +
            encodeURIComponent(jobId),
          {
            method: "GET"
          }
        );

      const productionStatus =
        String(
          production.status ||
          production.data?.status ||
          ""
        ).toLowerCase();

      if (
        productionStatus === "queued" ||
        productionStatus === "pending" ||
        productionStatus === "generating" ||
        productionStatus === "processing" ||
        productionStatus === "running"
      ) {
        if (statusMsg) {
          statusMsg.innerText =
            "Generating video, please wait...";
        }

        continue;
      }

      if (
        productionStatus === "completed" ||
        productionStatus === "complete" ||
        productionStatus === "success" ||
        productionStatus === "succeeded"
      ) {
        const completedMedia =
          production.generatedMedia ||
          production.data?.generatedMedia ||
          {};

        const completedVideoUrl =
          production.videoUrl ||
          production.finalVideoUrl ||
          production.url ||
          completedMedia.video ||
          completedMedia.url ||
          production.data?.videoUrl ||
          production.data?.finalVideoUrl ||
          production.data?.url ||
          "";

        if (!completedVideoUrl) {
          throw new Error(
            "GaveAI completed the video but no video URL was returned."
          );
        }

        if (statusMsg) {
          statusMsg.remove();
        }

        displayGeneratedVideo(
          completedVideoUrl
        );

        if (inputEl) {
          inputEl.value = "";
        }

        return;
      }

      if (
        productionStatus === "failed" ||
        productionStatus === "error" ||
        productionStatus === "cancelled" ||
        productionStatus === "canceled"
      ) {
        throw new Error(
          production.error ||
          production.message ||
          production.data?.error ||
          production.data?.message ||
          "GaveAI could not generate the video. Please try again."
        );
      }

      if (statusMsg) {
        statusMsg.innerText =
          "Generating video, please wait...";
      }
    }
  } catch (error) {
    console.error(
      "Video generation error:",
      error
    );

    if (statusMsg) {
      statusMsg.innerText =
        error?.message ||
        "GaveAI could not generate the video. Please try again.";
    }
  } finally {
    if (genBtn) {
      genBtn.disabled = false;
    }
  }
};
function updateFreeVideoDisplay(remaining) {
  const el =
    document.getElementById("aiCreditsDisplay");

  if (!el) return;

  const count = Math.max(
    0,
    Number(remaining) || 0
  );

  if (count > 0) {
    el.innerHTML =
      '<span>🎁 Free Video: ' +
      count +
      ' available</span>' +
      '<span style="margin-left:10px;font-weight:600;opacity:.95;">Create images, videos, stories and complete connected videos with AI.</span>';
  } else {
    el.innerHTML =
      '<span>🎁 Free Video: Used</span>' +
      '<span style="margin-left:10px;font-weight:600;opacity:.95;">Create images, videos, stories and complete connected videos with AI.</span>';
  }
}

async function refreshFreeVideoDisplay() {
  try {
    const data = await fetchJsonSafe(
      GAVEAI_BACKEND_URL + "/api/account",
      {
        method: "GET"
      }
    );

    if (
      data &&
      data.user &&
      data.user.freeVideoRemaining !== undefined
    ) {
      updateFreeVideoDisplay(
        data.user.freeVideoRemaining
      );
    }
  } catch (error) {
    console.warn(
      "Could not refresh GaveAI free video status:",
      error
    );
  }
}

window.toggleAIBox = function() {
  const aiBox =
    document.getElementById("aiBox");

  if (!aiBox) return;

  const willOpen =
    !aiBox.classList.contains("open");

  aiBox.classList.toggle("open");

  if (willOpen) {
    refreshFreeVideoDisplay();
  }
};
window.triggerAiAction = function(actionText) {
  const input = document.getElementById("aiInput");
  if (input) { input.value = actionText; window.sendAiMessage(false); }
};

/* ==========================================
   STORYBOARD WORKSPACE (RESTORED)
   ========================================== */
const storyboardScenes = [];
let storyboardNextId = 1;
let storyboardActiveSceneId = null;

window.storyboardGetActiveSceneId = function() {
  if (storyboardActiveSceneId !== null &&
      storyboardScenes.some(scene => scene.id === storyboardActiveSceneId)) {
    return storyboardActiveSceneId;
  }

  if (storyboardScenes.length > 0) {
    storyboardActiveSceneId = storyboardScenes[0].id;
    return storyboardActiveSceneId;
  }

  return null;
};

window.storyboardSetActiveScene = function(sceneId) {
  const scene = storyboardScenes.find(s => s.id === sceneId);
  if (!scene) return;

  storyboardActiveSceneId = sceneId;

  document.querySelectorAll('.sb-scene-card').forEach(card => {
    card.classList.toggle(
      'active',
      Number(card.dataset.sceneId) === Number(sceneId)
    );
  });
};

window.openStoryboard = function() {
  const overlay = document.getElementById('storyboardOverlay');
  if (overlay) {
    overlay.classList.add('open');
    if (storyboardScenes.length === 0) {
      window.storyboardAddScene();
    } else {
      window.storyboardRenderScenes();
    }
  }
};

window.closeStoryboard = function() {
  const overlay = document.getElementById('storyboardOverlay');
  if (overlay) overlay.classList.remove('open');
};

window.storyboardAddScene = function() {
  const newSceneId = storyboardNextId++;

  storyboardScenes.push({
    id: newSceneId,
    prompt: '',
    duration: 5,
    imageUrl: '',
    firstFrameImage: '',
    lastFrameImage: '',
    voiceText: '',
    dialogue: '',
    narration: '',
    voiceEmotion: '',
    voiceSpeed: 1.0,
    musicPrompt: '',
    musicVolume: 0.7,
    sfxPrompt: '',
    sfxVolume: 0.7,
    ambiencePrompt: '',
    ambienceVolume: 0.5
  });

  storyboardActiveSceneId = newSceneId;
  window.storyboardRenderScenes();
};

window.storyboardDeleteScene = function(sceneId) {
  const idx = storyboardScenes.findIndex(s => s.id === sceneId);
  if (idx > -1) {
    storyboardScenes.splice(idx, 1);

    if (storyboardScenes.length === 0) {
      storyboardActiveSceneId = null;
    } else if (storyboardActiveSceneId === sceneId) {
      const nextScene = storyboardScenes[Math.min(idx, storyboardScenes.length - 1)];
      storyboardActiveSceneId = nextScene.id;
    }

    window.storyboardRenderScenes();
  }
};

window.storyboardMoveScene = function(sceneId, direction) {
  const idx = storyboardScenes.findIndex(s => s.id === sceneId);
  if (idx === -1) return;
  const newIdx = idx + direction;
  if (newIdx < 0 || newIdx >= storyboardScenes.length) return;

  const temp = storyboardScenes[idx];
  storyboardScenes[idx] = storyboardScenes[newIdx];
  storyboardScenes[newIdx] = temp;

  storyboardActiveSceneId = sceneId;
  window.storyboardRenderScenes();
};

window.storyboardUpdateScene = function(sceneId, field, value) {
  const scene = storyboardScenes.find(s => s.id === sceneId);
  if (!scene) return;
  scene[field] = value;
  window.storyboardUpdateStats();
};

