window.storyboardUpdateStats = function() {
  const sceneCount = storyboardScenes.length;
  let totalDuration = 0;
  let totalCredits = 0;

  storyboardScenes.forEach(scene => {
    totalDuration += scene.duration || 5;
    totalCredits += (scene.duration === 8) ? 24 : 15;
  });

  const sceneCountEl = document.getElementById('sbSceneCount');
  const durationEl = document.getElementById('sbTotalDuration');
  const creditsEl = document.getElementById('sbTotalCredits');
  const estimatedEl = document.getElementById('sbEstimatedCredits');

  if (sceneCountEl) sceneCountEl.textContent = sceneCount;
  if (durationEl) durationEl.textContent = totalDuration;
  if (creditsEl) creditsEl.textContent = totalCredits;
  if (estimatedEl) estimatedEl.textContent = totalCredits;
};

window.storyboardGenerateImage = async function(sceneId) {
  const scene = storyboardScenes.find(s => s.id === sceneId);
  if (!scene) return;

  storyboardActiveSceneId = sceneId;
  window.storyboardSetActiveScene(sceneId);

  const storyOverview = document.getElementById('sbStoryOverview')?.value || '';
  const mainCharacter = document.getElementById('sbMainCharacter')?.value || '';
  const visualStyle = document.getElementById('sbVisualStyle')?.value || '';
  const environment = document.getElementById('sbEnvironment')?.value || '';

  const continuity = [
    storyOverview ? "Story: " + storyOverview : "",
    mainCharacter ? "Main Character: " + mainCharacter : "",
    visualStyle ? "Style: " + visualStyle : "",
    environment ? "Environment: " + environment : ""
  ].filter(Boolean).join(". ");

  const userScenePrompt = String(scene.prompt || "").trim();

  const strictImagePrompt = `
STRICT IMAGE GENERATION INSTRUCTION.

USER SCENE REQUEST:
${userScenePrompt || "Generate the requested scene exactly as described."}

GLOBAL STORY CONTEXT:
${continuity || "No additional global story context was provided."}

PROMPT FOLLOWING RULES:
- Follow the user's scene request exactly.
- The user's scene request is the primary instruction.
- Do not add people, objects, animals, clothing, props, locations, backgrounds, actions, or visual elements that were not requested.
- Do not remove anything explicitly requested by the user.
- Do not change race, ethnicity, skin tone, gender, age, identity, facial features, hairstyle, body shape, clothing, or accessories unless explicitly requested.
- Do not change the requested environment or background unless explicitly requested.
- Do not change the requested camera angle, framing, distance, perspective, composition, or subject scale unless explicitly requested.
- Do not create a close-up, zoom, crop, or different camera view unless explicitly requested.
- Keep all requested subjects and important objects naturally inside the frame.
- Do not crop heads, faces, feet, hands, or important objects unless explicitly requested.
- Do not stretch, compress, enlarge, or distort people or objects.
- Preserve natural body proportions and spatial relationships.
- Do not beautify, redesign, reinterpret, or creatively modify unrelated parts of the request.
- Do not invent missing story details when the user has not requested them.
- Use the global story context only to maintain continuity with the requested scene.
- If the global story context conflicts with the user's specific scene request, follow the specific scene request.
- Generate only the image described by the user.

FRAME AND COMPOSITION:
- Fit requested subjects naturally inside the frame.
- Keep the full requested subject visible when the user did not request a crop.
- Preserve natural scale and proportions.
- Avoid accidental close-ups.
- Avoid accidental cropping.
- Avoid unnatural stretching or oversized subjects.
- Use a cinematic composition only when it does not conflict with the user's request.
`;

  const fullPrompt = strictImagePrompt;

  console.log("GAVEAI: generating scene image", scene.id);

  try {
    const data = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/generate-image", {
      method: "POST",
      body: JSON.stringify({
        prompt: fullPrompt,
        width: 1280,
        height: 720,
        seed: -1
      })
    });

    const imageUrl = data.url || data.imageUrl || (data.generatedMedia && data.generatedMedia.url);
    if (imageUrl) {
      scene.imageUrl = imageUrl;
      scene.firstFrameImage = imageUrl;
      window.storyboardRenderScenes();
      console.log("GAVEAI: scene image generated", scene.id);
    }
  } catch (error) {
    console.error("Scene image generation error:", error);
    console.error("GAVEAI scene image generation failed:", error);
  }
};

window.storyboardUploadImage = function(sceneId) {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/png,image/jpeg,image/webp';
  input.onchange = async function() {
    if (!input.files || !input.files[0]) return;
    const file = input.files[0];
    const scene = storyboardScenes.find(s => s.id === sceneId);
    if (!scene) return;

    try {
      const url = await uploadToImageKit(file, 'image');
      if (url) {
        scene.imageUrl = url;
        scene.firstFrameImage = url;
        window.storyboardRenderScenes();
        console.log("GAVEAI: scene image uploaded", scene.id);
      }
    } catch (error) {
      console.error("Scene image upload error:", error);
      console.error("GAVEAI scene image upload failed:", error);
    }
  };
  input.click();
};

window.storyboardUploadVideo = function(sceneId) {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = "video/mp4,video/webm,video/quicktime";

  input.onchange = async function() {
    if (!input.files || !input.files[0]) return;

    const file = input.files[0];
    const scene = storyboardScenes.find(function(item) {
      return Number(item.id) === Number(sceneId);
    });

    if (!scene) {
      console.error("GAVEAI: no active scene selected for video upload.");
      return;
    }

    try {
      const url = await uploadToImageKit(file, "video");

      if (url) {
        scene.videoUrl = url;
        window.storyboardRenderScenes();
        console.log("GAVEAI: scene video uploaded", scene.id);
      }
    } catch (error) {
      console.error("GAVEAI scene video upload failed:", error);
    }
  };

  input.click();
};
window.storyboardSetStatus = function(message, type) {
  const workspace = document.querySelector(".storyboard-workspace");
  if (!workspace) return;

  let status = document.getElementById("sbWorkspaceStatus");

  if (!status) {
    status = document.createElement("div");
    status.id = "sbWorkspaceStatus";
    status.className = "sb-workspace-status";
    workspace.insertBefore(status, workspace.querySelector(".sb-main"));
  }

  status.className = "sb-workspace-status " + (type || "info");
  status.textContent = String(message || "");
};

window.storyboardRenderFinalVideo = function(videoUrl) {
  const workspace = document.querySelector(".storyboard-workspace");
  if (!workspace || !videoUrl) return;

  let result = document.getElementById("sbFinalVideoResult");

  if (!result) {
    result = document.createElement("div");
    result.id = "sbFinalVideoResult";
    result.className = "sb-final-video-result";

    const main = workspace.querySelector(".sb-main");

    if (main) {
      main.parentNode.insertBefore(result, main);
    } else {
      workspace.appendChild(result);
    }
  }

  result.innerHTML =
    '<div class="sb-final-video-title">Final Connected Video</div>' +
    '<video src="' + videoUrl + '" controls playsinline></video>' +
    '<div class="sb-final-video-actions">' +
      '<a href="' + videoUrl + '" target="_blank" rel="noopener" class="sb-final-video-action">Open Video</a>' +
      '<a href="#" onclick="event.preventDefault(); window.forceDownload(\'' + videoUrl + '\', \'gaveai-final-video.mp4\')" class="sb-final-video-action">Download Video</a>' +
    '</div>';

  result.style.display = "block";
};

window.storyboardGenerateFinal = async function() {
  if (storyboardScenes.length === 0) {
    window.storyboardSetStatus("Please add at least one scene.", "error");
    return;
  }

  const btn = document.getElementById("sbGenerateFinalBtn");

  if (btn) {
    btn.disabled = true;
    btn.innerHTML = "Generating connected video...";
  }

  const storyOverview =
    document.getElementById("sbStoryOverview")?.value || "";

  const mainCharacter =
    document.getElementById("sbMainCharacter")?.value || "";

  const supportingCharacters =
    document.getElementById("sbSupportingCharacters")?.value || "";

  const visualStyle =
    document.getElementById("sbVisualStyle")?.value || "";

  const environment =
    document.getElementById("sbEnvironment")?.value || "";

  const cameraStyle =
    document.getElementById("sbCameraStyle")?.value || "";

  const globalAudioDirection =
    document.getElementById("sbGlobalAudio")?.value || "";

  const scenePrompts = storyboardScenes
    .map(function(scene, index) {
      const prompt = String(scene.prompt || "").trim();

      if (!prompt) {
        return "Scene " + (index + 1) + ": Continue the connected story using the available scene context.";
      }

      return "Scene " + (index + 1) + ": " + prompt;
    })
    .join("\n");

  const storyboardPrompt = [
    "STRICT GAVEAI VIDEO GENERATION INSTRUCTION.",
    "",
    "USER STORY REQUEST:",
    storyOverview,
    "",
    "MAIN CHARACTER:",
    mainCharacter,
    "",
    "SUPPORTING CHARACTERS:",
    supportingCharacters,
    "",
    "VISUAL STYLE:",
    visualStyle,
    "",
    "ENVIRONMENT:",
    environment,
    "",
    "CAMERA STYLE:",
    cameraStyle,
    "",
    "GLOBAL AUDIO DIRECTION:",
    globalAudioDirection,
    "",
    "SCENE REQUESTS:",
    scenePrompts,
    "",
    "PROMPT FOLLOWING RULES:",
    "- Follow the user's requested story and scene instructions exactly.",
    "- Preserve the user's requested characters, identities, appearance, clothing, objects, environment, camera style, and actions.",
    "- Do not invent unrelated characters, objects, locations, actions, or visual elements.",
    "- Do not remove anything explicitly requested by the user.",
    "- Maintain visual continuity between connected scenes.",
    "- Use global story context only to maintain continuity.",
    "- If a specific scene request conflicts with global context, follow the specific scene request.",
    "- Preserve the requested language and meaning of dialogue, narration, and audio direction.",
    "- Generate the connected video from the provided scene sequence."
  ].join("\n");

  const payload = {
    prompt: storyboardPrompt,
    storyOverview: storyOverview,
    mainCharacter: mainCharacter,
    supportingCharacters: supportingCharacters,
    visualStyle: visualStyle,
    environment: environment,
    cameraStyle: cameraStyle,
    globalAudioDirection: globalAudioDirection,

    scenes: storyboardScenes.map(function(scene) {
      return {
        prompt: String(scene.prompt || "").trim(),
        duration: scene.duration || 5,
        firstFrameImage: scene.firstFrameImage || scene.imageUrl || null,
        lastFrameImage: scene.lastFrameImage || null,
        videoUrl: scene.videoUrl || null,
        voiceText: scene.voiceText || scene.dialogue || scene.narration || "",
        dialogue: scene.dialogue || "",
        narration: scene.narration || "",
        voiceEmotion: scene.voiceEmotion || "",
        voiceSpeed: scene.voiceSpeed || 1.0,
        voicePitch: scene.voicePitch || 0,
        voiceLanguage: scene.voiceLanguage || null,
        voiceId: scene.voiceId || null,
        languageBoost: scene.languageBoost || null,
        musicPrompt: scene.musicPrompt || "",
        musicVolume: scene.musicVolume || 0.7,
        sfxPrompt: scene.sfxPrompt || "",
        sfxVolume: scene.sfxVolume || 0.7,
        ambiencePrompt: scene.ambiencePrompt || "",
        ambienceVolume: scene.ambienceVolume || 0.5
      };
    }),

    width: 832,
    height: 480,
    seed: -1
  };

  const totalCredits = storyboardScenes.reduce(function(sum, scene) {
    return sum + ((scene.duration === 8) ? 24 : 15);
  }, 0);

  window.storyboardSetStatus(
    "Generating final connected video (" +
    totalCredits +
    " credits, " +
    storyboardScenes.length +
    " scenes). This may take several minutes.",
    "loading"
  );

  try {
    const data = await fetchJsonSafe(
      GAVEAI_BACKEND_URL + "/generate-video",
      {
        method: "POST",
        body: JSON.stringify(payload)
      }
    );

    if (data.freeVideoRemaining !== undefined) {
      updateFreeVideoDisplay(data.freeVideoRemaining);
    }

    const immediateVideoUrl =
      (data.generatedMedia && data.generatedMedia.video) ||
      (data.generatedMedia && data.generatedMedia.url) ||
      data.finalVideoUrl ||
      data.videoUrl ||
      data.url;

    if (immediateVideoUrl) {
      window.storyboardRenderFinalVideo(immediateVideoUrl);

      window.storyboardSetStatus(
        "Final connected video generated successfully. Audio embedded.",
        "success"
      );

      return;
    }

    const jobId =
      data.jobId ||
      data.videoJobId ||
      data.productionId ||
      "";

    if (!jobId) {
      throw new Error(
        "GaveAI did not return a video production job ID."
      );
    }

    const pollingStartedAt = Date.now();
    const pollingTimeoutMs = 15 * 60 * 1000;
    const pollingIntervalMs = 3000;

    while (true) {
      if (Date.now() - pollingStartedAt >= pollingTimeoutMs) {
        throw new Error(
          "Video generation is taking longer than expected. Please check the Storyboard workspace again shortly."
        );
      }

      await new Promise(function(resolve) {
        setTimeout(resolve, pollingIntervalMs);
      });

      const statusData = await fetchJsonSafe(
        GAVEAI_BACKEND_URL +
          "/api/video-productions/" +
          encodeURIComponent(jobId),
        {
          method: "GET"
        }
      );

      const production =
        statusData &&
        statusData.production
          ? statusData.production
          : statusData;

      const productionStatus =
        String(
          production && production.status
            ? production.status
            : ""
        ).toLowerCase();

      if (
        productionStatus === "queued" ||
        productionStatus === "pending"
      ) {
        window.storyboardSetStatus(
          "Your connected video is queued. Please wait...",
          "loading"
        );
        continue;
      }

      if (
        productionStatus === "generating" ||
        productionStatus === "processing" ||
        productionStatus === "running"
      ) {
        window.storyboardSetStatus(
          "Generating final connected video. Please wait...",
          "loading"
        );
        continue;
      }

      if (
        productionStatus === "completed" ||
        productionStatus === "complete" ||
        productionStatus === "success" ||
        productionStatus === "succeeded"
      ) {
        const completedVideoUrl =
          production.videoUrl ||
          production.finalVideoUrl ||
          production.url ||
          (production.generatedMedia &&
            (
              production.generatedMedia.video ||
              production.generatedMedia.url
            ));

        if (!completedVideoUrl) {
          throw new Error(
            "Video generation completed, but GaveAI did not return the final video URL."
          );
        }

        window.storyboardRenderFinalVideo(
          completedVideoUrl
        );

        window.storyboardSetStatus(
          "Final connected video generated successfully. Audio embedded.",
          "success"
        );

        if (
          production.freeVideoRemaining !== undefined
        ) {
          updateFreeVideoDisplay(
            production.freeVideoRemaining
          );
        }

        return;
      }

      if (
        productionStatus === "failed" ||
        productionStatus === "error" ||
        productionStatus === "cancelled" ||
        productionStatus === "canceled"
      ) {
        throw new Error(
          production.error ||
          "GaveAI could not generate the final connected video. Please try again."
        );
      }

      window.storyboardSetStatus(
        "Generating final connected video. Please wait...",
        "loading"
      );
    }
  } catch (error) {
    console.error(
      "Final video generation error:",
      error
    );

    window.storyboardSetStatus(
      error && error.message
        ? String(error.message)
        : "GaveAI could not generate the final connected video. Please try again.",
      "error"
    );
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = "Generate Final Connected Video";
    }
  }
};
