function filterByCategory(cat) {
  currentDisplayedJobs = cat === 'all' ? [...verifiedCompaniesList] : verifiedCompaniesList.filter(j => j.category === cat);
  renderJobs(currentDisplayedJobs);
  const board = document.getElementById('gmt-job-board');
  if (board) board.scrollIntoView({ behavior: 'smooth' });
}

function filterByKeyword(kw) {
  const query = kw.toLowerCase().trim();
  currentDisplayedJobs = verifiedCompaniesList.filter(j => j.title.toLowerCase().includes(query) || j.company.toLowerCase().includes(query) || j.category.toLowerCase().includes(query));
  renderJobs(currentDisplayedJobs);
  const board = document.getElementById('gmt-job-board');
  if (board) board.scrollIntoView({ behavior: 'smooth' });
}

