function getSavedJobIds() { try { return JSON.parse(localStorage.getItem('gmt_saved_jobs') || '[]'); } catch(e) { return []; } }

function toggleSaveJob(id, btn) {
  let saved = getSavedJobIds();
  if (saved.includes(id)) { saved = saved.filter(function(item) { return item !== id; }); if (btn) { btn.classList.remove('saved'); btn.innerHTML = 'ÃƒÆ’Ã‚Â°Ãƒâ€¦Ã‚Â¸ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“ Save'; } }
  else { saved.push(id); if (btn) { btn.classList.add('saved'); btn.innerHTML = 'ÃƒÆ’Ã‚Â¢Ãƒâ€¦Ã¢â‚¬Å“ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Saved'; } }
  localStorage.setItem('gmt_saved_jobs', JSON.stringify(saved));
  updateSavedCounter();
}

