      }
    });
  });
  const searchBtn = document.getElementById('jobSearchSubmit');
  if (searchBtn) { searchBtn.addEventListener('click', function() { const kw = document.getElementById('jobKeyword').value.trim(); if (kw) filterByKeyword(kw); }); }
  setupAutocomplete('jobKeyword', 'mainAutocomplete');
  setupAutocomplete('headerSearchInput', 'headerAutocomplete');
  if (document.getElementById('gmt-jobs-list')) { renderJobs(currentDisplayedJobs); markJobsAsUpdated(); updateSavedCounter(); }
  if (document.getElementById('posts-make-money-online')) {
    loadCategoryPosts('Make money online', 'posts-make-money-online');
    loadCategoryPosts('Freelancing', 'posts-freelancing');
    loadCategoryPosts('Digital Marketing', 'posts-digital-marketing');
    loadCategoryPosts('Affiliate Marketing', 'posts-affiliate-marketing');
    loadCategoryPosts('Earning Apps', 'posts-earning-apps');
    loadCategoryPosts('Blogging', 'posts-blogging');
    loadCategoryPosts('AI Tools', 'posts-ai-tools');
    loadCategoryPosts('Remote Jobs', 'posts-remote-jobs');
    loadCategoryPosts('Passive Income', 'posts-passive-income');
    loadCategoryPosts('Learn English', 'posts-learn-english');
  }
})();

